tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD:$PWD/packages/worldkeeper/src TMPDIR=/tmp
PY=.venv/bin/python
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $2}' | sort)
[ -n "$CH" ] || { echo "WHY: nothing changed"; exit 1; }
for f in $CH; do case "$f" in storygame/runtime/knowledge.py|storygame/runtime/state.py|tests/test_knowledge_narrated_gate.py|tests/test_richer_1c_voice.py|tests/test_concealment_repro.py|tests/test_knowledge_projection.py|tests/test_defect_probe.py|tests/test_voiceable_knowledge.py|tests/test_environment_smoke_direct.py|tests/test_underside_exhausted.py|tests/test_richer_1b_value.py|tests/test_bench.py|tests/test_open_probe.py|tests/test_speaker_lines.py|tests/test_cloudflare_transport.py) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
echo "$CH" | grep -qx storygame/runtime/knowledge.py || { echo "WHY: knowledge.py not changed"; exit 1; }
echo "$CH" | grep -qx storygame/runtime/state.py || { echo "WHY: state.py not changed"; exit 1; }
echo "$CH" | grep -qx tests/test_knowledge_narrated_gate.py || { echo "WHY: new test file missing"; exit 1; }
grep -q 'knowledge_narrated' storygame/runtime/state.py || { echo "WHY: fact not asserted in state.py"; exit 1; }
[ "$(grep -c '^def test_\|^    def test_' tests/test_knowledge_narrated_gate.py)" -ge 7 ] || { echo "WHY: fewer than 7 tests in new file"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_knowledge_narrated_gate.py tests/test_richer_1c_voice.py tests/test_concealment_repro.py tests/test_knowledge_projection.py tests/test_defect_probe.py tests/test_voiceable_knowledge.py tests/test_environment_smoke_direct.py tests/test_underside_exhausted.py tests/test_richer_1b_value.py tests/test_bench.py tests/test_open_probe.py tests/test_speaker_lines.py tests/test_cloudflare_transport.py 2>&1 | tail -25 | tee /tmp/gate-pytest.txt
[ "${PIPESTATUS[0]}" = 0 ] || { echo "WHY: tests failed"; exit 1; }
$PY -m ruff check storygame/runtime/knowledge.py storygame/runtime/state.py tests/test_knowledge_narrated_gate.py || exit 1
$PY -m ruff format --check storygame/runtime/knowledge.py storygame/runtime/state.py tests/test_knowledge_narrated_gate.py || exit 1
git add -A -- storygame tests
git diff --cached > /home/bcorfman/dev/ringer-work/shared-narrator-gate/gate.patch
[ -s /home/bcorfman/dev/ringer-work/shared-narrator-gate/gate.patch ] || { echo "WHY: empty patch"; exit 1; }
echo "patch ok: $(wc -l < /home/bcorfman/dev/ringer-work/shared-narrator-gate/gate.patch) lines"
